package com.mobilelab.vibrodiag

import com.mobilelab.vibrodiag.features.FeatureNames
import com.mobilelab.vibrodiag.features.FeaturePipeline
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test
import java.io.File
import kotlin.math.abs
import kotlin.math.max

/**
 * Cross-language parity check: the Kotlin feature extractor must produce the
 * same numbers as the Python pipeline (analysis/vibro/features.py) on the same
 * WAV/accelerometer files. The reference values are the synthetic demo
 * features that were generated by the Python implementation.
 *
 * Tolerance follows docs/feature_spec.md section 4: relative error < 1e-3 with
 * an absolute floor that covers the 6-decimal CSV rounding.
 */
class FeatureParityTest {

    @Test
    fun kotlinFeaturesMatchPythonReference() {
        val sessionDir = locateDemoSession()
        assumeTrue("demo dataset not available, skipping parity check", sessionDir != null)
        val groupDir = File(sessionDir, "C1_NORMAL_LOW/g01")
        assumeTrue("demo group missing", groupDir.isDirectory)

        val audio = File(groupDir, "g01_C1_NORMAL_LOW_audio.wav")
        val accel = File(groupDir, "g01_C1_NORMAL_LOW_accel.csv")
        val reference = File(groupDir, "g01_C1_NORMAL_LOW_features.csv")
        assumeTrue("demo files missing", audio.isFile && accel.isFile && reference.isFile)

        val kotlinFeatures = FeaturePipeline.extractFromFiles(audio, accel)
        val pythonValues = parseReference(reference)

        val failures = mutableListOf<String>()
        var worst = 0.0
        var worstName = ""
        for (name in FeatureNames.numeric) {
            val k = kotlinFeatures[name]
            val p = pythonValues[name]
            if (k == null || p == null || k.isNaN() || p.isNaN()) {
                failures += "$name: kotlin=$k python=$p"
                continue
            }
            val diff = abs(k - p)
            val allowed = 1e-6 + 1e-3 * abs(p)
            val ratio = diff / max(abs(p), 1e-9)
            if (ratio > worst) {
                worst = ratio
                worstName = name
            }
            if (diff > allowed) {
                failures += String.format(java.util.Locale.US, "%s: kotlin=%.8f python=%.8f diff=%.3e", name, k, p, diff)
            }
        }
        println("parity: $worstName worst relative error=$worst")
        assertTrue(
            "Kotlin/Python feature mismatch (" + failures.size + " of " + FeatureNames.numeric.size + "):\n" +
                failures.joinToString("\n"),
            failures.isEmpty(),
        )
    }

    private fun locateDemoSession(): File? {
        val candidates = listOf(
            "../../data/demo/vibro/20261118_VD-20261118-001",
            "../data/demo/vibro/20261118_VD-20261118-001",
            "data/demo/vibro/20261118_VD-20261118-001",
        )
        return candidates.map { File(it) }.firstOrNull { it.isDirectory }
    }

    private fun parseReference(file: File): Map<String, Double?> {
        val lines = file.readLines().filter { it.isNotBlank() }
        require(lines.size >= 2) { "reference CSV has no data row" }
        val header = lines[0].removePrefix("\uFEFF").split(",")
        val values = lines[1].split(",")
        val map = HashMap<String, Double?>()
        header.forEachIndexed { index, name ->
            val raw = values.getOrNull(index)?.trim().orEmpty()
            map[name] = raw.toDoubleOrNull()
        }
        return map
    }
}
